    for _ in range(t):
        n = int(input[index])
        index += 1
        p = list(map(int, input[index:index+n]))
        index += n
        if n == 2:
            results.append([p[1], p[0]])
        else:
            p_prime = p[:]
            for i in range(1, n-1):
                if p[i] != p_prime[i]:
                    break
                if p[i-1] < p[i+1]:
                    p_prime[i], p_prime[i+1] = p_prime[i+1], p_prime[i]
                elif p[i-1] > p[i+1]:
                    p_prime[i-1], p_prime[i] = p_prime[i], p_prime[i-1]
            else:
                p_prime[0], p_prime[1] = p_prime[1], p_prime[0]
            results.append(p_prime)
    for result in results:
        print(" ".join(map(str, result)))

